GLOSSARY = [
    ("Transaction Intent", "What the document does (12 intents, e.g. transfer of ownership, security for loan, right to use); filters the Nature of Document list."),
    ("Nature of Document", "Type of instrument (59 natures, e.g. Sale Deed, Gift Deed, Lease, Power of Attorney) mapped to the Articles of the Schedule."),
    ("Article", "Entry in the Schedule to the Karnataka Stamp Act, 1957 that fixes the duty for the instrument (e.g. Article 20(1) conveyance)."),
    ("Guidance value (GV)", "Market value guideline published by the Central Valuation Committee (Sec. 45-B); calculated by the Guidance Value service."),
    ("Market value", "Price the property would fetch if sold in the open market on the date of execution; duty is charged on the higher of declared consideration and guidance value for the Sec. 45-A instruments."),
    ("Stamp duty, surcharge, cess", "Duty under the Stamp Act and the additional levies collected with it, calculated by the Fee Calculation service."),
    ("Registration fee", "Fee under the Table of Registration Fees (Sec. 78), currently ₹20 per ₹1,000 under Article I(4)(a)."),
    ("Input catalogue", "List of the 119 stamp duty input fields (IDs such as GEN-08, LSE-03) that the system may ask for, with data type, allowed values, source and purpose (3.v.e)."),
    ("Family (for stamp duty)", "Relationships that attract the concessional family rate for gift 28(b), settlement 48-A(ii), release 45(b) and lease 30(1), or exclude 41(eb); defined by the family definitions table (3.v.d)."),
    ("Local body limits (LL-1 / LL-2 / LL-3)", "Classification of the property location (Corporation / BMRDA; CMC / TMC / Town Panchayat; other areas) that fixes the family-rate duty."),
    ("Principal instrument", "Where several instruments complete one sale, mortgage or settlement, the instrument that pays the full duty; the others pay ₹100 (Sec. 4)."),
    ("Average annual rent", "Total rent for the term divided by the number of years (rent for the term if less than a year), derived from the rent schedule (GR-10)."),
    ("JDA", "Joint Development Agreement between a land owner and a developer (Article 5(f); PoA 41(ea))."),
    ("MDPA", "Mine Development and Production Agreement / mining lease (Article 30(3))."),
    ("Denoting / credit", "Set-off of duty already paid on an earlier instrument (Sec. 16 and Rule 18; agreements 5(e), PoA 41(e)/(eb), lease-cum-sale 5(d) between the same parties)."),
    ("Discretionary exemption", "Exemption that needs the Sub-Registrar's approval; payment is held as Pending Verification until approved (one per application)."),
    ("Source of truth", "Authoritative property system: E-Swathu, BBMP E-Aasthi, E-Aasthi, BDA, KHB (non-agricultural), Bhoomi RTC and Mojini (agricultural)."),
    ("Deed Generation service", "Microservice that picks the approved deed template for the nature of document and instrument sub-type and generates the draft deed, final deed, endorsement and registered document (PDF)."),
    ("Stays & Liabilities", "Microservice that checks government / court stays, 22-B stays, Sec. 22-A prohibited properties, land restrictions and liabilities."),
    ("Execution / date of execution", "Signing of the deed; in Kaveri 3.0 each party's e-Sign date is that party's date of execution."),
    ("Presentation", "Formal submission of the executed document to the Sub-Registrar by a person entitled under Sec. 32."),
    ("Admission of execution", "Executant's acknowledgement before the Sub-Registrar that they executed the document (Sec. 34, 35)."),
    ("Party Appearance Pending", "Status while some executants have not yet appeared and admitted (Sec. 34(2); Rule 172)."),
    ("Summons / commission", "Means of securing the appearance or examination of an absent executant (Sec. 31, 33, 36–39)."),
    ("Condonation", "District Registrar's order excusing delay in presentation or appearance up to a further 4 months on payment of a fine (Sec. 25, 34; Rules 51–55)."),
    ("Impounding", "Retention of an instrument not duly stamped and its referral for duty and penalty (Stamp Act Sec. 33, 37, 39)."),
    ("Sec. 45-A reference", "Reference of an under-valued instrument to the Deputy Commissioner / District Registrar for determination of market value."),
    ("Endorsement", "Statutory particulars endorsed on the document: presentation, admission, identification, fees, condonation (Sec. 58–60; Rule 55(ii))."),
    ("Refusal order", "Order of the Sub-Registrar refusing registration with recorded reasons (Sec. 71; Rule 171), entered in Book 2."),
    ("Withdrawal", "Return of a document at the presenter's written request before registration (Rules 23(f), 193(i)); not a refusal."),
    ("e-Sign", "Aadhaar OTP-based electronic signature through an e-Sign service provider."),
    ("DSC", "Digital Signature Certificate on a token issued by a certifying authority; used by officers and optionally by parties."),
    ("e-KYC", "Aadhaar-based electronic identity verification through UIDAI."),
    ("Form 97", "Declaration by an individual party without PAN, as modelled in the pre-registration diagram (above ₹45 lakh: proof of PAN application also needed)."),
    ("Khajane-II", "Government of Karnataka integrated treasury system used for challans, receipts and refund bills."),
    ("e-stamp certificate", "Certificate issued through the e-stamping system (Central Record-keeping Agency) as proof of stamp duty paid."),
    ("TDR", "Transferable Development Rights certificate issued by BBMP / BDA."),
    ("Mojini", "Survey sketch system for agricultural land; provides transferees and sketch details for part sales."),
]

