NFR_INTRO = ("To ensure the Kaveri 3.0 Document Registration module operates reliably, securely and efficiently, the following "
             "non-functional parameters shall be built into the system architecture. They apply to the citizen portal, the "
             "Sub-Registrar and District Registrar back office, the capture counter and the microservices.")
NFR = [
    ("Performance and Scalability", "Response time, concurrency and elasticity targets below are mandatory load-test gates before production. Surge capacity is needed at financial-year end, on auspicious days and around revisions of guidance value or duty rates.", [
        ("NFR-DOC-PERF-001", "Standard UI interactions shall complete within 2 seconds and external integration calls (source of truth, e-KYC, e-Sign, payment) within 5 seconds at p95.", "Must", "Load-test report at the concurrency in NFR-DOC-PERF-002"),
        ("NFR-DOC-PERF-002", "The platform shall support at least 10,000 concurrent citizen sessions and 3,000 concurrent office users across Sub-Registrar Offices.", "Must", "No SLA breach at the stated concurrency"),
        ("NFR-DOC-PERF-003", "Guidance Value and Fee Calculation services shall return results within 1 second at p95.", "Must", "Service-level benchmark"),
        ("NFR-DOC-SCALE-001", "Infrastructure shall scale automatically for a 300% surge above baseline.", "Must", "Surge test without manual scale-up"),
    ]),
    ("Security and Data Privacy", "Encryption, PII protection and auditability are baseline controls. Aadhaar / e-KYC use is subject to UIDAI and Department approval.", [
        ("NFR-DOC-SEC-001", "Data in transit shall use TLS 1.3; data at rest (documents, PII, biometrics) AES-256.", "Must", "Configuration evidence from hosting"),
        ("NFR-DOC-PRIV-001", "Aadhaar numbers shall be masked / tokenised (Aadhaar Data Vault); biometrics stored only as permitted; PII masked in logs.", "Must", "No raw Aadhaar in logs or reports"),
        ("NFR-DOC-AUD-001", "All state changes (submission, scrutiny decisions, payments, signatures, presentation, admission, endorsement, registration, refusal, withdrawal, orders, refunds) shall create an append-only audit event with actor, time, previous / next state and reason.", "Must", "Audit trail reviewable per application"),
        ("NFR-DOC-SEC-002", "Role-based access by office and role (citizen, SR, DEO, District Registrar, IGR, Deputy Commissioner of Stamps, admin); officers act only within their jurisdiction.", "Must", "Access tests per role"),
        ("NFR-DOC-SEC-003", "The locked deed and registered documents shall be tamper-evident (hash and digital signature).", "Must", "Hash verification on retrieval"),
    ]),
    ("System Availability and Error Handling", "The module shall fail safely when an external dependency is unavailable and shall never collect fees twice.", [
        ("NFR-DOC-AVA-001", "Availability of 99.5% during office hours; planned maintenance outside office hours.", "Must", "Monthly availability report"),
        ("NFR-DOC-AVA-002", "If an external integration is down, the user shall see a bilingual reason and the application shall stay resumable at the same step.", "Must", "Outage simulation tests"),
        ("NFR-DOC-PAY-001", "On a payment timeout the system shall poll for the final status and block a second payment until resolved.", "Must", "No double debit in tests"),
    ]),
    ("Security Audit and Compliance (VAPT Policy)", "Vulnerability Assessment and Penetration Testing is mandatory; automated scanning alone does not satisfy the gate.", [
        ("NFR-DOC-VAPT-001", "The application shall pass a CERT-In empanelled VAPT before go-live and after every major release.", "Must", "Accepted VAPT report"),
        ("NFR-DOC-VAPT-002", "Scope shall cover web, APIs, microservices, payment, e-Sign / DSC flows, biometric capture and the mobile signing links (OWASP Top 10, business logic).", "Must", "Scope statement signed off"),
        ("NFR-DOC-VAPT-003", "Critical and high findings shall be fixed and re-tested before go-live.", "Must", "Zero open Critical / High at go-live"),
    ]),
]

